static void blit_mario_pipe(int x, int y) {
  if (x >= 128 || y >= 32 || x + 16 <= 0 || y + 20 <= 0) return;
  int x0 = (x < 0) ? -x : 0;
  int y0 = (y < 0) ? -y : 0;
  int x1 = (x + 16 > 128) ? 128 - x : 16;
  int y1 = (y + 20 > 32)  ? 32 - y  : 20;
  static uint16_t rowbuf[16];
  for (int row = y0; row < y1; row++) {
    memcpy_P(rowbuf, &mario_pipe[row*16], 16*2);
    int dy = y + row;
    for (int col = x0; col < x1; col++) {
      uint16_t c = rowbuf[col];
      if (c) display->drawPixel(x + col, dy, c);
    }
  }
}
