// Color565 helper (inlined for speed)
static uint16_t c565(uint8_t r, uint8_t g, uint8_t b) {
  return ((r >> 3) << 11) | ((g >> 2) << 5) | (b >> 3);
}

// Draw a 5x7 font character at (x,y) using direct pixel drawing
static void drawFontChar(int x, int y, char ch, uint16_t color) {
  int idx = -1;
  for (int i = 0; i < 11; i++) { if (font_chars[i] == ch) { idx = i; break; } }
  if (idx < 0) return;
  uint8_t rows[7];
  memcpy_P(rows, font5x7[idx], 7);
  for (int row = 0; row < 7; row++) {
    for (int col = 0; col < 5; col++) {
      if (rows[row] & (0x10 >> col))
        display->drawPixel(x+col, y+row, color);
    }
  }
}

// Draw a 5x7 font character at 4x scale (each pixel becomes a 4x4 block = 20x28 px)
// Used by large-digit artistic themes (Neon, Matrix, Fire, Rainbow)
static void drawLargeFontChar(int x, int y, char ch, uint16_t color) {
  int idx = -1;
  for (int i = 0; i < 11; i++) { if (font_chars[i] == ch) { idx = i; break; } }
  if (idx < 0) return;
  uint8_t rows[7];
  memcpy_P(rows, font5x7[idx], 7);
  for (int row = 0; row < 7; row++) {
    for (int col = 0; col < 5; col++) {
      if (rows[row] & (0x10 >> col))
        display->fillRect(x + col*4, y + row*4, 4, 4, color);
    }
  }
}

static void drawTimeHHMM(int x, int y, int h, int m, uint16_t color) {
  char buf[5];
  buf[0] = '0' + h/10; buf[1] = '0' + h%10; buf[2] = ':';
  buf[3] = '0' + m/10; buf[4] = '0' + m%10;
  for (int i = 0; i < 5; i++) drawFontChar(x + i*6, y, buf[i], color);
}

// Draw a 5x7 font character at 2x horizontal scale only (10x7 px).
// Used by Pac-Man's enlarged clock: bolder/wider without growing tall enough
// to collide with sprites running along the top/bottom edges of its loop.
static void drawWideFontChar(int x, int y, char ch, uint16_t color) {
  int idx = -1;
  for (int i = 0; i < 11; i++) { if (font_chars[i] == ch) { idx = i; break; } }
  if (idx < 0) return;
  uint8_t rows[7];
  memcpy_P(rows, font5x7[idx], 7);
  for (int row = 0; row < 7; row++) {
    for (int col = 0; col < 5; col++) {
      if (rows[row] & (0x10 >> col))
        display->fillRect(x + col*2, y + row, 2, 1, color);
    }
  }
}

// Rounded (corner-cut) power pellet — replaces a plain filled square.
static void drawPowerPellet(int cx, int cy, uint16_t color) {
  display->fillRect(cx-1, cy-2, 3, 5, color);
  display->fillRect(cx-2, cy-1, 5, 3, color);
}

// Blit a raw RGB565 sprite with optional horizontal flip and optional solid
// tint (used for Pac-Man ghosts: flip = facing left/right, tinted = frightened).
static void blit_ghost_sprite(const uint16_t *data, int w, int h, int x, int y, bool flip, bool tinted, uint16_t tintColor) {
  if (x >= 128 || y >= 32 || x + w <= 0 || y + h <= 0) return;
  int x0 = (x < 0) ? -x : 0;
  int y0 = (y < 0) ? -y : 0;
  int x1 = (x + w > 128) ? 128 - x : w;
  int y1 = (y + h > 32)  ? 32 - y  : h;
  static uint16_t rowbuf[16];
  for (int row = y0; row < y1; row++) {
    memcpy_P(rowbuf, &data[row*w], w*2);
    int dy = y + row;
    for (int col = x0; col < x1; col++) {
      uint16_t c = rowbuf[flip ? (w - 1 - col) : col];
      if (c) display->drawPixel(x + col, dy, tinted ? tintColor : c);
    }
  }
}

// Direction of travel along the Pac-Man loop for a given dot index:
// 0=right (top edge), 1=down (right edge), 2=left (bottom edge), 3=up (left edge)
static int pacPathDir(int idx) {
  if (idx >= 0 && idx < 24) return 0;
  else if (idx >= 24 && idx < 30) return 1;
  else if (idx >= 30 && idx < 54) return 2;
  else if (idx >= 54 && idx < 60) return 3;
  else return 0;
}

// Classic 500ms on/off blink shared by every clock theme's ':' separator.
// Centralizes the (ms/1000)%2 rule that used to be copy-pasted independently
// in Tetris, Neon, Matrix, Fire, Rainbow, Pong, Invaders and Pac-Man.
static bool isColonHidden(char ch, unsigned long ms) {
  return (ch == ':') && ((ms / 1000) % 2 == 0);
}

// ── THEME 1: SUPER MARIO ────────────────────
// World 1-1's opening moment, looped: sky/ground colors match the NES
// palette (the sky constant already existed but a previous pass drew an
// unrelated navy instead of using it), a fixed brick-?-brick-?-brick
// cluster and pipe like the level's actual opening, a Goomba, and Mario
// running the strip then clearing it with a real parabolic jump -- not
// perpetually bouncing props with no basis in actual play (a cycling
// pipe, a mushroom bobbing forever by itself, ? blocks bobbing on a
// loop) like the previous pass had. HUD bar reuses the game's own "TIME"
// field for the real clock, which is the one piece of the HUD that's
// actually meaningful here.
static void drawTheme_Mario(int h, int m, int s, unsigned long ms) {
  const int groundY = 26;
  // Sky fills the whole panel now that the HUD bar is gone -- the constant
  // already matched the NES palette, a previous pass just wasn't using it.
  display->fillRect(0, 0, 128, groundY, 26047);

  // Three-layer parallax: hills (far, slow, big) -> pipes (mid) -> ground/
  // Goomba/bushes (near, fast). Mario himself stays at a fixed screen x and
  // just runs in place / jumps -- the world scrolls past him, which is what
  // actually makes this parallax instead of just "background elements
  // drifting behind a Mario who's also independently walking across."
  // Cheap either way: it's the same "shift an x by ms/rate, wrap with %"
  // trick per layer, just at three different rates -- no extra pixels
  // drawn, only a different offset in each layer's position formula.
  const int nearRate = 20, midRate = 50, farRate = 150;

  // Hills: muted teal-green (not the bush's saturated green) so they read
  // as a distinct, distant layer. Widest row first (nearest the ground),
  // narrowing toward the peak -- these were drawn upside-down before
  // (narrowest at the base) because the loop paired the wrong end of the
  // width table with the row closest to the ground.
  uint16_t hillColor = c565(45,125,115);
  static const uint8_t hillW[9] = {44,44,42,38,32,24,16,8,3};
  int hillScroll = (int)((ms / farRate) % 130);
  for (int hx = -130; hx < 260; hx += 130) {
    int cx = hx - hillScroll;
    for (int i = 0; i < 9; i++) {
      int w = hillW[i];
      display->fillRect(cx - w/2, groundY - 1 - i, w, 1, hillColor);
    }
  }

  // Clouds drift across the sky, their own independent (slow) rate.
  int cx1 = 128 - (ms / 80) % 220;
  int cx2 = 128 - (ms / 110 + 90) % 220;
  int cx3 = 128 - (ms / 65 + 160) % 220;
  blit_mario_cloud(cx1, 1);
  blit_mario_cloud(cx2, 6);
  blit_mario_cloud(cx3, 3);

  // Pipes: mid layer, two staggered so one is always roughly on screen.
  const int pipeSpriteW = 16, pipeY = groundY - 20;
  int pipeX1 = 220 - (int)((ms / midRate) % 260);
  int pipeX2 = 220 - (int)(((ms / midRate) + 130) % 260);
  blit_mario_pipe(pipeX1, pipeY);
  blit_mario_pipe(pipeX2, pipeY);

  // Ground: a repeating blocky brick tile, seam scroll at the near rate so
  // it visually matches the Goomba/bushes moving "with" it.
  display->fillRect(0, groundY, 128, 32 - groundY, 46023);
  display->fillRect(0, groundY, 128, 1, c565(220,170,110));
  int groundScroll = (int)((ms / nearRate) % 12);
  for (int x = -groundScroll; x < 128; x += 12) display->fillRect(x, groundY, 1, 32 - groundY, 31299);
  display->fillRect(0, groundY + 4, 128, 1, 31299);

  // Bushes: near layer, two staggered, same rate as the ground/Goomba.
  int bushX1 = 170 - (int)((ms / nearRate) % 160);
  int bushX2 = 170 - (int)(((ms / nearRate) + 80) % 160);
  blit_mario_bush(bushX1, groundY - 5);
  blit_mario_bush(bushX2, groundY - 5);

  // Goomba: near layer too (same rate as the ground) so it reads as
  // actually standing on the ground that's scrolling past, walk-animating
  // (leg swap) independently of its scroll position.
  const int goombaSpriteW = 12, goombaY = groundY - 12;
  int goombaX = 170 - (int)((ms / nearRate) % 200);
  bool goombaFrame = (ms / 200) % 2;
  if (goombaFrame) blit_mario_goomba_walk0(goombaX, goombaY);
  else blit_mario_goomba_walk1(goombaX, goombaY);

  // Mario: fixed screen position (the world scrolls past him instead), leg
  // animation while grounded, and a real parabolic jump timed off the
  // Goomba's scrolling x reaching him -- always centered since both are
  // computed from ms, not from an independent per-frame accumulator.
  const int marioSpriteH = 17, marioSpriteW = 17, marioX = 30;
  int marioY = groundY - marioSpriteH;
  const int jumpHalfSpan = 15, jumpHeight = 12;
  int distFromGoomba = (goombaX + goombaSpriteW/2) - (marioX + marioSpriteW/2);
  bool jumping = distFromGoomba > -jumpHalfSpan && distFromGoomba < jumpHalfSpan;
  if (jumping) {
    int t256 = ((distFromGoomba + jumpHalfSpan) * 256) / (2*jumpHalfSpan);
    int arc = (t256 * (256 - t256)) >> 8;
    marioY -= (arc * jumpHeight) / 64;
    blit_mario_mario_jump(marioX, marioY);
  } else {
    bool mf = (ms / 120) % 2;
    if (mf) blit_mario_mario_run1(marioX, marioY);
    else blit_mario_mario_run0(marioX, marioY);
  }

  // Time, small in the corner -- no background box, just the digits.
  // Noir (pas blanc) : le blanc se lit mal sur le fond ciel clair du DMD reel.
  uint16_t hudDark = c565(0,0,0);
  drawTimeHHMM(97, 1, h, m, hudDark);
}

// ── THEME 10: LEVEL 1-1 ──────────────────────
// A separate theme from Super Mario (which is untouched) -- no character,
// no parallax (single shared scroll speed for the whole level), just a
// wide seamless-looping recreation of World 1-1's ground-level landmarks
// end to end: opening blocks, pipes of three heights, two differently
// arranged brick/? clusters, a pyramid staircase, a run-up staircase, the
// flagpole, and the castle. Every feature is drawn at both `offset` and
// `offset + PATTERN_WIDTH` screen positions each frame (only whichever is
// actually within/entering the visible 128px is ever non-clipped) so the
// wrap-around is seamless -- same trick already proven this session for
// clouds/pipes/bushes, just applied to one shared position instead of each
// element's own independent cycle.
static void drawTheme_Level11(int h, int m, int s, unsigned long ms) {
  const int groundY = 26;
  display->fillRect(0, 0, 128, groundY, 26047);

  // Clouds: independent slow drift, not part of the level's own scroll.
  int cx1 = 128 - (ms / 80) % 220;
  int cx2 = 128 - (ms / 110 + 90) % 220;
  int cx3 = 128 - (ms / 65 + 160) % 220;
  blit_mario_cloud(cx1, 1);
  blit_mario_cloud(cx2, 6);
  blit_mario_cloud(cx3, 3);

  const int rate = 20; // px per 20ms -- same near-layer speed validated this session
  const long PATTERN_WIDTH = 700;
  long wp = (long)(ms / rate) % PATTERN_WIDTH;

  // Ground: solid band with a scrolling brick-seam pattern, same style as
  // the Super Mario theme's ground -- except for two gaps (visual pits,
  // there's no character to actually fall in) cut out of it below.
  display->fillRect(0, groundY, 128, 32 - groundY, 46023);
  display->fillRect(0, groundY, 128, 1, c565(220,170,110));
  int groundScroll = (int)((ms / rate) % 12);
  for (int x = -groundScroll; x < 128; x += 12) display->fillRect(x, groundY, 1, 32 - groundY, 31299);
  display->fillRect(0, groundY + 4, 128, 1, 31299);
  // Punch the two ground gaps back out to sky color.
  int gapOffsets[2] = {230, 650};
  int gapW = 16;
  for (int gi = 0; gi < 2; gi++) {
    int sx = gapOffsets[gi] - (int)wp;
    for (int rep = 0; rep < 2; rep++) {
      int gx = sx + rep * PATTERN_WIDTH;
      if (gx + gapW > 0 && gx < 128) display->fillRect(gx, groundY, gapW, 32 - groundY, 26047);
    }
  }

  // Pipes: collar bitmap + a procedurally repeated 1px-tall shaded body
  // slice, so three different heights share one sprite.
  struct { int off, height; } pipes[3] = { {50, 14}, {190, 18}, {380, 24} };
  for (int pi = 0; pi < 3; pi++) {
    int sx0 = pipes[pi].off - (int)wp;
    int ph = pipes[pi].height;
    for (int rep = 0; rep < 2; rep++) {
      int px = sx0 + rep * PATTERN_WIDTH;
      if (px < -20 || px > 148) continue;
      int py = groundY - ph;
      blit_mario_lvl_pipe_collar(px, py);
      for (int row = 4; row < ph; row++) {
        display->fillRect(px + 2, py + row, 1, 1, 28296);
        display->fillRect(px + 3, py + row, 10, 1, 9476);
        display->fillRect(px + 13, py + row, 1, 1, 2785);
      }
    }
  }

  // Two block clusters, differently arranged so they don't look identical.
  const int blockY = 3;
  {
    int base = 90 - (int)wp;
    int seq1X[5] = {0, 12, 24, 36, 48};
    bool seq1Q[5] = {false, true, false, true, false};
    for (int i = 0; i < 5; i++) {
      for (int rep = 0; rep < 2; rep++) {
        int bx = base + seq1X[i] + rep * PATTERN_WIDTH;
        if (bx < -14 || bx > 142) continue;
        if (seq1Q[i]) blit_mario_lvl_question_block(bx, blockY); else blit_mario_lvl_brick(bx, blockY);
      }
    }
  }
  {
    int base = 420 - (int)wp;
    int seq2X[4] = {0, 25, 37, 62};
    bool seq2Q[4] = {true, false, false, true};
    for (int i = 0; i < 4; i++) {
      for (int rep = 0; rep < 2; rep++) {
        int bx = base + seq2X[i] + rep * PATTERN_WIDTH;
        if (bx < -14 || bx > 142) continue;
        if (seq2Q[i]) blit_mario_lvl_question_block(bx, blockY); else blit_mario_lvl_brick(bx, blockY);
      }
    }
  }

  // Pyramid staircase (up then down) and a one-way run-up staircase near
  // the flagpole -- solid brick-colored columns with a couple of scroll-
  // synced seam lines instead of stacking full 11px brick sprites (which
  // would blow through the 26px sky budget after 2-3 levels).
  {
    int base = 270 - (int)wp;
    int stepX[5] = {0, 12, 24, 36, 48};
    int stepH[5] = {7, 14, 21, 14, 7};
    for (int i = 0; i < 5; i++) {
      for (int rep = 0; rep < 2; rep++) {
        int cx0 = base + stepX[i] + rep * PATTERN_WIDTH;
        if (cx0 < -12 || cx0 > 140) continue;
        int ch = stepH[i];
        display->fillRect(cx0, groundY - ch, 11, ch, 46023);
        display->fillRect(cx0, groundY - ch, 11, 1, c565(220,170,110));
        for (int sy = groundY - ch + 5; sy < groundY; sy += 5) display->fillRect(cx0, sy, 11, 1, 31299);
      }
    }
  }
  {
    int base = 560 - (int)wp;
    int stepX[4] = {0, 12, 24, 36};
    int stepH[4] = {7, 14, 21, 21};
    for (int i = 0; i < 4; i++) {
      for (int rep = 0; rep < 2; rep++) {
        int cx0 = base + stepX[i] + rep * PATTERN_WIDTH;
        if (cx0 < -12 || cx0 > 140) continue;
        int ch = stepH[i];
        display->fillRect(cx0, groundY - ch, 11, ch, 46023);
        display->fillRect(cx0, groundY - ch, 11, 1, c565(220,170,110));
        for (int sy = groundY - ch + 5; sy < groundY; sy += 5) display->fillRect(cx0, sy, 11, 1, 31299);
      }
    }
  }

  // Flagpole: thin pole reaching near the sky's top, small triangular flag.
  {
    int base = 620 - (int)wp;
    for (int rep = 0; rep < 2; rep++) {
      int fx = base + rep * PATTERN_WIDTH;
      if (fx < -6 || fx > 134) continue;
      display->fillRect(fx, 2, 1, groundY - 2, c565(220,220,220));
      display->fillRect(fx + 1, 2, 5, 1, 9476);
      display->fillRect(fx + 1, 3, 4, 1, 9476);
      display->fillRect(fx + 1, 4, 3, 1, 9476);
      display->fillRect(fx - 1, 2, 3, 3, c565(240,240,240));
    }
  }

  // Castle: crenellated top, solid body, dark doorway -- sized to use most
  // of the sky height as a strong "end of level" silhouette.
  {
    int base = 670 - (int)wp;
    uint16_t castleColor = c565(150,90,70);
    int cw = 26, ch = 22;
    for (int rep = 0; rep < 2; rep++) {
      int bx = base + rep * PATTERN_WIDTH;
      if (bx < -cw || bx > 128 + cw) continue;
      int topY = groundY - ch;
      for (int cxOff = 0; cxOff < cw; cxOff += 6) display->fillRect(bx + cxOff, topY, 3, 3, castleColor);
      display->fillRect(bx, topY + 3, cw, ch - 3, castleColor);
      display->fillRect(bx + cw/2 - 3, groundY - 7, 6, 7, c565(20,15,15));
      display->fillRect(bx + 4, topY + 8, 3, 3, c565(20,15,15));
      display->fillRect(bx + cw - 7, topY + 8, 3, 3, c565(20,15,15));
    }
  }

  // Time, small in the corner, HH:MM:SS -- no background box, and the
  // extra SS field (this theme has no other use of that corner's width).
  // Noir (pas blanc) : le blanc se lit mal sur le fond ciel clair du DMD reel.
  uint16_t hudDark = c565(0,0,0);
  char tbuf[9];
  tbuf[0]='0'+h/10; tbuf[1]='0'+h%10; tbuf[2]=':';
  tbuf[3]='0'+m/10; tbuf[4]='0'+m%10; tbuf[5]=':';
  tbuf[6]='0'+s/10; tbuf[7]='0'+s%10; tbuf[8]=0;
  int timeX = 74;
  for (int i = 0; i < 8; i++) {
    if (isColonHidden(tbuf[i], ms)) continue;
    drawFontChar(timeX + i*6, 1, tbuf[i], hudDark);
  }
}

// Saint Basil's Cathedral, redone after the Tengen/NES Tetris title screen
// (the user's second reference -- a tight cluster of 5 domes dominated by a
// ribbed red-orange tent tower, sitting almost flush with the bottom edge).
// Earlier passes kept the domes in a strip above the clock box so nothing
// would overlap; this one instead fills the whole panel bottom-up and lets
// the clock box get drawn on top afterward, masking whatever domes sit
// behind it -- matching the reference, where the frame isn't reserved space.

// Onion dome: widest about a third of the way down, then a sharp pinch into
// a short neck/drum -- the abrupt shoulder is what reads as "onion" rather
// than "conifer". Alternates two closely-related tones per row for a
// subtle ribbed look; pass the same color twice for a flat dome.
static void drawOnion(int cx, int groundY, const uint8_t *widths, int n, uint16_t colorA, uint16_t colorB, uint16_t drumColor, uint16_t accent) {
  for (int i = 0; i < n; i++) {
    int w = widths[i];
    int half = w >> 1;
    int y = groundY - 3 - (n - i);
    uint16_t col = i == 0 ? accent : ((i & 1) == 0 ? colorA : colorB);
    display->fillRect(cx - half, y, w, 1, col);
  }
  display->fillRect(cx - 1, groundY - 3, 2, 1, drumColor);
  display->fillRect(cx - 1, groundY - 2, 2, 2, drumColor);
}
// Zoomed-in hero tower: fills most of the panel by itself. Earlier passes
// kept all 5 domes in frame, which meant every one of them was only 5-8px
// wide -- too small for any real surface detail to read. Cropping down to
// one tower and blowing it up instead leaves room for a shaded cap, a
// thick-banded fluted cone, and drum-level arch detail, matching the
// user's call: a partial, detailed view beats a complete, flat one.
static void drawMegaTower(int cx, int groundY, uint16_t coneA, uint16_t coneB, uint16_t capA, uint16_t capB, uint16_t drumColor, uint16_t archColor, uint16_t accent) {
  // Cone: 20 rows, tapering 12 -> 28 wide, in thick 2-row bands so the
  // ribbing is chunky and legible instead of a 1px hairline pattern.
  const int coneRows = 20, coneTop = 8;
  for (int i = 0; i < coneRows; i++) {
    int w = 12 + (i * 16) / (coneRows - 1);
    int half = w >> 1;
    int band = (i >> 1) & 1;
    display->fillRect(cx - half, coneTop + i, w, 1, band == 0 ? coneA : coneB);
  }
  // Cap: onion dome with horizontal-band shading -- a per-pixel checker at
  // this size (max 9px wide) compresses down to a blur; bands 2px thick
  // read clearly as a shaded, textured bulb instead.
  static const uint8_t capRows[7] = {2,4,7,9,10,10,9};
  for (int i = 0; i < 7; i++) {
    int w = capRows[i];
    int half = w >> 1;
    display->fillRect(cx - half, i, w, 1, ((i >> 1) & 1) == 0 ? capA : capB);
  }
  display->fillRect(cx - 1, 0, 2, 1, accent); // spire tip
  // Drum with a couple of small dark arch-window slits, then a flared base.
  int drumTop = coneTop + coneRows;
  display->fillRect(cx - 5, drumTop, 11, 5, drumColor);
  display->fillRect(cx - 3, drumTop + 1, 2, 3, archColor);
  display->fillRect(cx + 1, drumTop + 1, 2, 3, archColor);
  display->fillRect(cx - 8, groundY - 3, 17, 3, drumColor);
}
static void drawSaintBasils(unsigned long ms) {
  const int x0 = 55, groundY = 31;
  // dusk sky fading into near-black at the horizon, like the reference
  display->fillRect(x0, 0, 128 - x0, 4, c565(18,10,28));
  display->fillRect(x0, 4, 128 - x0, 4, c565(45,18,38));
  display->fillRect(x0, 8, 128 - x0, 6, c565(80,30,34));
  display->fillRect(x0, 14, 128 - x0, groundY - 14, c565(30,14,20));

  uint16_t gold = c565(228,184,64), goldHi = c565(250,214,110), white = c565(238,238,244);
  uint16_t drumDark = c565(35,20,18);

  // twinkling stars -- drawn before the tower so its silhouette naturally
  // occludes any star that falls within its footprint
  static const uint8_t starX[7]     = {58,64,71,76,90,102,118};
  static const uint8_t starY[7]     = {2,6,3,7,2,1,1};
  static const uint16_t starPhase[7] = {0,60,140,20,200,90,160};
  for (int i = 0; i < 7; i++) {
    int idx = (int)(((ms + starPhase[i]) / 6) & 255);
    int8_t b = sin8[idx];
    if (b > 70) display->drawPixel(starX[i], starY[i], white);
    else if (b > -10) display->drawPixel(starX[i], starY[i], c565(150,150,180));
  }

  drawMegaTower(80, groundY, c565(175,55,35), c565(210,90,40), c565(232,190,70), goldHi, drumDark, c565(18,10,10), white);

  // small blue-and-white dome tucked under the clock frame, on the right
  static const uint8_t domeW[9] = {1,3,5,7,9,10,10,9,7};
  drawOnion(111, groundY, domeW, 9, c565(60,110,205), white, drumDark, c565(255,255,255));

  // base / arcade band with a few arch hints, spanning the whole width --
  // implies the building continues past the frame either side of the tower
  display->fillRect(x0, groundY, 128 - x0, 1, c565(60,32,20));
  display->fillRect(x0, groundY + 1, 128 - x0, 1, c565(35,16,12));
  for (int x = x0 + 2; x < 125; x += 6) display->fillRect(x, groundY - 1, 3, 1, c565(50,26,18));

  // Firework: a rocket climbs with a fading trail, then bursts into a
  // multi-color shower of sparks that drift outward and fall under gravity.
  // Uses the existing integer sin8 table (not sinf/cosf, which this
  // codebase avoids elsewhere -- see the "avoids sinf() crashes" note on
  // sin8's declaration) for the radial spread.
  const unsigned long LAUNCH_DUR = 350, BURST_DUR = 950, PERIOD = 3600;
  unsigned long t = ms % PERIOD;
  int fcx = x0 + 16;
  if (t < LAUNCH_DUR) {
    int ny = 13 - (int)(9 * t / LAUNCH_DUR);
    display->drawPixel(fcx, ny, c565(255,240,210));
    display->drawPixel(fcx, ny + 1, c565(180,90,40));
    display->drawPixel(fcx, ny + 2, c565(90,40,20));
  } else if (t < LAUNCH_DUR + BURST_DUR) {
    unsigned long t2 = t - LAUNCH_DUR;
    int cy = 4;
    unsigned long fadeStart = BURST_DUR * 55 / 100;
    const int nSparks = 14;
    uint16_t palette[3]    = { c565(255,220,120), c565(150,200,255), c565(255,255,255) };
    uint16_t dimPalette[3] = { c565(120,100,60), c565(70,95,120), c565(120,120,120) };
    for (int k = 0; k < nSparks; k++) {
      int angIdx = (k * 256 / nSparks) & 255;
      int speed10 = 60 + (k % 3) * 25; // desired radius*10 at full extension
      int rad10 = (int)(t2 * speed10 / BURST_DUR); // radius*10, grows over the burst
      long fall10 = (long)(t2 * t2) * 50 / ((long)BURST_DUR * BURST_DUR); // gravity droop*10
      int px = fcx + (sin8[(angIdx + 64) & 255] * rad10) / 1270;
      int py = cy + (sin8[angIdx] * rad10 * 75) / (1270 * 100) + (int)(fall10 / 10);
      uint16_t col = t2 > fadeStart ? dimPalette[k % 3] : palette[k % 3];
      display->drawPixel(px, py, col);
    }
  }
}

// ── THEME 2: TETRIS ─────────────────────────
// Big blocks (4x4), vertical pieces, stacking at bottom
// Each piece is drawn as 4x4 pixel blocks with 1px gap
#define TETRIS_COLS 10
#define TETRIS_ROWS 8
static uint8_t tetrisGrid[TETRIS_ROWS][TETRIS_COLS];

static void tetrisGridClear() {
  for (int r = 0; r < TETRIS_ROWS; r++)
    for (int c = 0; c < TETRIS_COLS; c++)
      tetrisGrid[r][c] = 0xFF;
}

static void tetrisDrawBlock(int x, int y, uint16_t color) {
  display->fillRect(x, y, 4, 4, color);
  display->drawPixel(x+1, y+0, 0xFFFF); // highlight
  display->drawPixel(x+0, y+1, 0xFFFF);
  display->drawPixel(x+3, y+2, 0x0000); // shadow
  display->drawPixel(x+2, y+3, 0x0000);
}

static void drawTheme_Tetris(int h, int m, int s, unsigned long ms) {
  static bool gridInit = false;
  if (!gridInit) { tetrisGridClear(); gridInit = true; }
  display->fillRect(0, 0, 128, 32, c565(0,0,20));

  // Pending pieces animation on the left
  uint16_t pieceColors[7] = { c565(0,255,255), c565(255,255,0), c565(180,0,255),
    c565(0,220,0), c565(220,0,0), c565(0,80,255), c565(255,160,0) };
  // Piece shapes: each is bitmask 4x4 (bits MSB=leftmost)
  const uint8_t tShapes[7][4] = {
    {0x8, 0x8, 0x8, 0x8}, // I: vertical line PW=1
    {0xC, 0xC, 0, 0},     // O: 2x2 square PW=2
    {0xE, 0x4, 0, 0},     // T: row0=111 row1=010 PW=3
    {0x6, 0xC, 0, 0},     // S: row0=011 row1=110 PW=3
    {0xC, 0x6, 0, 0},     // Z: row0=110 row1=011 PW=3
    {0x8, 0xE, 0, 0},     // J: row0=100 row1=111 PW=3
    {0x2, 0xE, 0, 0},     // L: row0=001 row1=111 PW=3
  };
  static const int tPW[7] = {1, 2, 3, 3, 3, 3, 3};

  // Persistent falling piece state
  static int tPiece = -1;
  static int tCol = 0;
  static int tRow = 0;
  static unsigned long tLastMs = 0;

  // ms is elapsed-since-this-theme-was-shown, so it resets to ~0 each time
  // the clock is displayed again; tLastMs persists from the previous
  // display though, and comparing a fresh small ms against an old large
  // tLastMs would underflow (unsigned) into a huge value and drop the
  // piece instantly. Resync instead.
  if (ms < tLastMs) tLastMs = ms;

  if (tPiece < 0) {
    tPiece = random(0, 7);
    tCol = random(0, TETRIS_COLS - tPW[tPiece] + 1);
    tRow = 0;
    tLastMs = ms;
  }

  bool lockPiece = false;

  if (ms - tLastMs >= 600) {
    int nextRow = tRow + 1;
    bool canGoDown = true;
    for (int r = 3; r >= 0 && canGoDown; r--)
      if (tShapes[tPiece][r] && nextRow + r >= TETRIS_ROWS) canGoDown = false;
    if (canGoDown) {
      for (int r = 0; r < 4; r++) {
        if (!tShapes[tPiece][r]) continue;
        int gr = nextRow + r;
        if (gr >= TETRIS_ROWS) break;
        for (int c = 0; c < tPW[tPiece]; c++)
          if (tShapes[tPiece][r] & (1 << (3-c)))
            if (tetrisGrid[gr][tCol+c] != 0xFF) { canGoDown = false; break; }
        if (!canGoDown) break;
      }
    }
    if (canGoDown) tRow = nextRow;
    else lockPiece = true;
    tLastMs = ms;
  }

  if (!lockPiece) {
    for (int r = 0; r < 4 && tRow+r < TETRIS_ROWS; r++) {
      if (!tShapes[tPiece][r]) continue;
      for (int c = 0; c < tPW[tPiece]; c++)
        if (tShapes[tPiece][r] & (1 << (3-c)))
          if (tetrisGrid[tRow+r][tCol+c] != 0xFF) { lockPiece = true; break; }
      if (lockPiece) break;
    }
  }

  if (lockPiece) {
    bool gameOver = false;
    for (int r = 0; r < 4 && tRow+r < TETRIS_ROWS; r++) {
      if (!tShapes[tPiece][r]) continue;
      for (int c = 0; c < tPW[tPiece]; c++) {
        if (tShapes[tPiece][r] & (1 << (3-c))) {
          if (tetrisGrid[tRow+r][tCol+c] != 0xFF) gameOver = true;
          else tetrisGrid[tRow+r][tCol+c] = tPiece;
        }
      }
    }
    if (gameOver) {
      tetrisGridClear();
    } else {
      for (int r = TETRIS_ROWS-1; r >= 0; r--) {
        bool full = true;
        for (int c = 0; c < TETRIS_COLS; c++)
          if (tetrisGrid[r][c] == 0xFF) { full = false; break; }
        if (full) {
          for (int r2 = r; r2 > 0; r2--)
            for (int c2 = 0; c2 < TETRIS_COLS; c2++)
              tetrisGrid[r2][c2] = tetrisGrid[r2-1][c2];
          for (int c2 = 0; c2 < TETRIS_COLS; c2++)
            tetrisGrid[0][c2] = 0xFF;
          r++;
        }
      }
    }
    tPiece = -1;
  }

  // Draw accumulated pieces from grid
  for (int r = 0; r < TETRIS_ROWS; r++) {
    for (int c = 0; c < TETRIS_COLS; c++) {
      if (tetrisGrid[r][c] != 0xFF)
        tetrisDrawBlock(4 + c*5, r*4, pieceColors[tetrisGrid[r][c]]);
    }
  }

  // Playfield border frame
  display->drawRect(3, 0, 51, 32, c565(60,60,100));

  // Draw falling piece
  if (tPiece >= 0) {
    for (int br = 0; br < 4 && tRow+br < TETRIS_ROWS; br++) {
      for (int bc = 0; bc < tPW[tPiece]; bc++) {
        if (tShapes[tPiece][br] & (1 << (3-bc))) {
          int px = 4 + (tCol+bc)*5;
          int py = (tRow+br)*4;
          tetrisDrawBlock(px, py, pieceColors[tPiece]);
        }
      }
    }
  }

  // The cathedral fills the whole panel bottom-up now; the clock box is
  // drawn on top afterward. Moved up to the top-right, which sits in clear
  // sky above every dome's shoulders (including the tower's cap), so it
  // now reads as a sign in the sky rather than cutting into the cathedral.
  drawSaintBasils(ms);
  display->fillRect(95, 2, 33, 11, c565(8,7,18));
  display->drawRect(95, 2, 33, 11, c565(90,80,140));
  uint16_t tc = pieceColors[(h+m+ms/200) % 7];
  char buf[5];
  buf[0] = '0'+h/10; buf[1] = '0'+h%10; buf[2]=':'; buf[3]='0'+m/10; buf[4]='0'+m%10;
  // Box interior (inside the 1px border) is x=96-126 (31 wide), y=3-11 (9
  // tall). Text is 29px wide x 7px tall, so centered start is x=97 (already
  // was), y=4 (was 5, leaving a 2px gap on top and 0 on the bottom instead
  // of an even 1px on each side).
  for (int i = 0; i < 5; i++) {
    if (isColonHidden(buf[i], ms)) continue;
    drawFontChar(97 + i*6, 4, buf[i], tc);
  }
}

// ── THEME 3: PAC-MAN ────────────────────────
// Yellow pellet path around screen, Pac-Man & 4 ghosts follow it.
// Eating a corner power pellet triggers a brief "frightened" (blue) window.
static void drawTheme_Pacman(int h, int m, int s, unsigned long ms) {
  display->fillRect(0, 0, 128, 32, c565(0,0,0));
  uint16_t dot = c565(255,200,100);
  uint16_t bigDot = c565(255,220,0);
  // Rectangular loop: top(24) + right(6) + bottom(24) + left(6) = 60 dots,
  // closing cleanly (index 59 lands on the exact same pixel as index 0).
  // This used to be followed by a second, near-duplicate top segment
  // (indices 60-83, same y=5 row) meant to "close" the loop back to the
  // start -- but it only made the loop 84 dots long while still only
  // visiting the right/bottom/left sides once, so wrapping from the end of
  // that extra segment back to index 0 was a same-row jump from x=124 back
  // to x=4: Pac-Man visibly vanished at the end of the top row and
  // reappeared at its start, and the two near-identical top rows drawing
  // over each other read as two superimposed animations.
  int totalDots = 60;
  int pathX[60], pathY[60];
  // Top: left to right (24 dots, 5px apart)
  for (int i = 0; i < 24; i++) { pathX[i] = 4 + i*5; pathY[i] = 5; }
  // Right: top to bottom (6 dots, 4px apart, stays on-screen)
  for (int i = 24; i < 30; i++) { pathX[i] = 124; pathY[i] = 6 + (i-24)*4; }
  // Bottom: right to left (24 dots, 5px apart)
  for (int i = 30; i < 54; i++) { pathX[i] = 119 - (i-30)*5; pathY[i] = 26; }
  // Left: bottom to top (6 dots, 4px apart) -- wraps straight back to index 0
  for (int i = 54; i < 60; i++) { pathX[i] = 4; pathY[i] = 25 - (i-54)*4; }

  // ---- Continuous position simulation ----
  // Pac-Man and each ghost carry a persistent, ever-advancing position
  // (fixed-point, PAC_SCALE milli-steps per path step) that this only
  // ever nudges by velocity*dt -- nothing here is ever recomputed "from
  // scratch" or snapped to a formula, so there's no discontinuity when
  // frightened mode starts or ends: whoever's wherever they currently are
  // just keeps moving from there, at whatever speed the new mode calls
  // for.
  const long PAC_SCALE = 1000;
  const long wrapSpan = (long)totalDots * PAC_SCALE;
  static const int CORNER_IDX[4] = {0, 23, 29, 53}; // top-left, top-right, bottom-right, bottom-left
  static const int CORNER_XY[4][2] = {{4,5}, {119,5}, {124,26}, {4,26}};
  static bool pacStateInit = false;
  static long pacLastMs = -1;
  static long pacPos = 0;
  static long ghostPos[4] = {0,0,0,0};
  static int pelletCorner = 3;
  static long pelletEatenAtMs = -1;
  static long respawnDelayMs = 0;
  static bool dotEaten[60] = {false};
  long dtMs;
  if (!pacStateInit || (long)ms < pacLastMs) {
    // Theme (re)started: reset to a deterministic opening state. The
    // first pellet starts at the bottom-left corner -- NOT index 0, where
    // Pac-Man himself spawns -- so he gets a full, normal run around most
    // of the loop first.
    pacStateInit = true;
    pacPos = 0;
    ghostPos[0] = ghostPos[1] = ghostPos[2] = ghostPos[3] = 0;
    pelletCorner = 3;
    pelletEatenAtMs = -1;
    respawnDelayMs = 0;
    for (int i = 0; i < 60; i++) dotEaten[i] = false;
    dtMs = 0;
  } else {
    dtMs = (long)ms - pacLastMs;
  }
  int pelletTrackIdx = CORNER_IDX[pelletCorner];

  // Frightened window, lengthened from ~2s to 4s, plus a random 1.5-4s gap
  // (no pellet at all on the track) before a new one appears at a
  // freshly-rolled corner.
  const int FRIGHT_STEPS = 40; // 4000ms total
  bool frightened = false;
  long frightSinceMs = 0;
  if (pelletEatenAtMs >= 0) {
    frightSinceMs = (long)ms - pelletEatenAtMs;
    if (frightSinceMs < FRIGHT_STEPS*100) {
      frightened = true;
    } else if (frightSinceMs < FRIGHT_STEPS*100 + respawnDelayMs) {
      frightened = false; // waiting gap: no pellet on the track yet
    } else {
      // Respawn time reached: 1-in-5, the pellet stays away a while longer
      // instead of reappearing. Rolling that 5th "nothing" option just
      // tacks another random wait onto the existing gap and rolls again
      // next time it elapses -- could skip more than once in a row.
      int choice = random(0, 5); // 0-3 = corner, 4 = stay empty
      if (choice < 4) {
        pelletCorner = choice;
        pelletEatenAtMs = -1;
      } else {
        respawnDelayMs += 1500 + random(0, 2500);
      }
    }
  }
  bool pelletVisible = pelletEatenAtMs < 0;
  int frightSinceSteps = frightSinceMs / 100;
  uint16_t frightColor = (frightened && frightSinceSteps > FRIGHT_STEPS - 6 && ((ms/150)%2))
                            ? c565(255,255,255) : c565(40,40,230);
  bool goingBackward = frightened;

  // Velocities, in milli-steps/ms. Pursuit = 1 step/100ms. Frightened:
  // constant speed, held steady for the whole panic duration (no easing
  // in, no easing out, no mid-panic change) -- but Pac-Man is the FASTER
  // one while giving chase, not the ghosts: he's gaining on them, which
  // is what actually reads as "pursuit". The gap is kept from ever
  // reaching zero by MIN_GAP below, not by making the ghosts outrun him.
  const long PURSUIT_VEL = 10;
  const long PAC_PANIC_VEL = -20;    // 2x pursuit speed, reversed -- faster than the ghosts' own
  const long GHOST_PANIC_VEL = -15;  // 1.5x pursuit speed, reversed
  const long GHOST_CATCHUP_VEL = 15; // 1.5x pursuit speed, forward -- see below
  const long GHOST_SLOWDOWN_VEL = 7; // 0.7x pursuit speed, forward -- see below

  int prevPacStepIdx = (int)(((pacPos/PAC_SCALE) % totalDots + totalDots) % totalDots);
  pacPos += (frightened ? PAC_PANIC_VEL : PURSUIT_VEL) * dtMs;
  // Re-center periodically to keep the accumulator bounded over long
  // uptimes, but ONLY by shifting Pac-Man's and every ghost's position by
  // the exact same multiple of a full lap at once -- that leaves every
  // pairwise gap between them completely unchanged, unlike wrapping each
  // position independently (which was a bug: once a ghost's continuous
  // position edged past Pac-Man's, wrapping it alone made it read as
  // "~59 steps behind" instead of "~1 step ahead", and catch-up took that
  // huge apparent gap as license to speed up even further).
  if (pacPos >= wrapSpan || pacPos < 0) {
    long wrapped = ((pacPos % wrapSpan) + wrapSpan) % wrapSpan; // in [0, wrapSpan)
    long shift = pacPos - wrapped;
    pacPos = wrapped;
    for (int g = 0; g < 4; g++) ghostPos[g] -= shift;
  }
  int pacStepIdx = (int)((pacPos/PAC_SCALE) % totalDots);

  // Pellet-eating: did Pac-Man's forward sweep this frame cross the
  // pellet's index? (A range check, not exact equality, so an occasional
  // long dtMs can't let him skip clean over it without triggering.)
  if (pelletVisible && !frightened) {
    int advanced = (pacStepIdx - prevPacStepIdx + totalDots) % totalDots;
    int distToPellet = (pelletTrackIdx - prevPacStepIdx + totalDots) % totalDots;
    if (distToPellet <= advanced) {
      pelletEatenAtMs = (long)ms;
      respawnDelayMs = 1500 + random(0, 2500); // 1.5-4s
    }
  }

  // Opening: all 4 ghosts start together at the same top-left corner
  // Pac-Man himself spawns at (track index 0) -- like emerging from the
  // ghost house -- staying parked (velocity 0) until he's pulled
  // ghostOffsets[g] steps ahead, at which point each releases and joins
  // the chase at pursuit speed.
  //
  // Pursuit-mode seeking: a ghost that's fallen further behind than its
  // normal trailing distance (e.g. coming out of a panic flight where
  // MIN_GAP let the gap widen again once he passed it) moves a bit FASTER
  // than pursuit speed to close back in; one that's ended up closer than
  // its normal distance (e.g. left at MIN_GAP right as panic ended) moves
  // a bit SLOWER, letting Pac-Man pull back out ahead -- still a plain
  // forward walk either way, never backward, never a teleport, until it
  // settles back to exactly Pac-Man's own pace at the right distance.
  // This is also what makes dot regeneration gradual during pursuit: the
  // eaten span's trailing edge is this ghost's own real, continuously-
  // advancing position, so dots reappear one at a time as it actually
  // sweeps forward past them, never all at once.
  int ghostOffsets[4] = {8, 14, 22, 30};
  // MIN_GAP is how close Pac-Man is ever allowed to get while chasing
  // during panic: once he's closed to within MIN_GAP steps of a ghost,
  // that ghost matches his (faster) pace exactly instead of continuing to
  // hold its own slower one, so the gap stops shrinking right there
  // instead of ever reaching zero -- "he chases, but never actually
  // touches one". During pursuit, the seek-catch-up-or-slow-down above
  // pulls the gap back toward ghostOffsets[g] from either side and holds
  // it there, so there's no separate cap needed on that end -- it's a
  // stable target, not a runaway.
  const int MIN_GAP = 5;
  int prevGhostBackIdx = (int)(((ghostPos[3]/PAC_SCALE) % totalDots + totalDots) % totalDots);
  int ghostVisIdx[4] = {0,0,0,0};
  bool ghostFlip[4] = {false, false, false, false};
  for (int g = 0; g < 4; g++) {
    unsigned long releaseMs = (unsigned long)ghostOffsets[g] * 100;
    long vel = 0;
    if (ms >= releaseMs) {
      // Signed, unwrapped gap in path steps -- positive means the ghost is
      // behind by that many steps, negative means it's ahead. Using the
      // raw continuous positions (not floored/modulo'd step indices)
      // avoids the "58 behind" vs "2 ahead" ambiguity that let a ghost
      // silently overtake Pac-Man before (see the note above pacPos's
      // re-centering).
      long curGapSteps = (pacPos - ghostPos[g]) / PAC_SCALE;
      if (frightened) {
        vel = curGapSteps > MIN_GAP ? GHOST_PANIC_VEL : PAC_PANIC_VEL;
      } else if (curGapSteps > ghostOffsets[g]) {
        vel = GHOST_CATCHUP_VEL;
      } else if (curGapSteps < ghostOffsets[g]) {
        vel = GHOST_SLOWDOWN_VEL;
      } else {
        vel = PURSUIT_VEL;
      }
    }
    ghostPos[g] += vel * dtMs;
    // Hard clamp, not just a converging velocity target: the vel choice
    // above only approaches the gap boundary gradually, so a single large
    // dtMs (a slow frame -- plausible on real hardware between WiFi/MQTT
    // work) could overshoot straight past it in one step. This guarantees
    // the ordering rule holds on every single frame regardless of dtMs:
    // ghosts strictly IN FRONT of Pac-Man while frightened (he's chasing
    // them), strictly BEHIND him during pursuit -- never the reverse.
    if (ms >= releaseMs) {
      if (frightened) {
        long minPos = pacPos - (long)MIN_GAP * PAC_SCALE;
        if (ghostPos[g] > minPos) ghostPos[g] = minPos;
      } else {
        long maxPos = pacPos - PAC_SCALE; // at least 1 step behind, never level or ahead
        if (ghostPos[g] > maxPos) ghostPos[g] = maxPos;
      }
    }
    ghostVisIdx[g] = (int)(((ghostPos[g]/PAC_SCALE) % totalDots + totalDots) % totalDots);
    int gDir = pacPathDir(ghostVisIdx[g]);
    if (gDir == 1 || gDir == 3) ghostFlip[g] = false; // vertical edges: never flip, per design
    else {
      bool normallyLeft = (gDir == 2);
      ghostFlip[g] = goingBackward ? !normallyLeft : normallyLeft;
    }
  }

  // Regular dots: each dot is individually marked eaten/regenerated the
  // instant Pac-Man or the trailing ghost's own continuous position
  // physically sweeps across it -- not derived from a two-point span -- and
  // only while pursuing. During frighten both of them run backward over
  // ground already resolved one way or the other, so no sweeping happens at
  // all there: every dot's state is exactly whatever it was the instant
  // frighten began. When pursuit resumes, Pac-Man and the ghost re-tread
  // that same backward stretch moving forward again; since it's already
  // marked correctly, re-marking it is a no-op, so nothing pops into view.
  // Only once either of them physically reaches genuinely new ground (past
  // wherever pursuit had gotten to before frighten started) does that dot's
  // state change -- one dot at a time, exactly as it's crossed.
  if (!frightened) {
    int advanced = (pacStepIdx - prevPacStepIdx + totalDots) % totalDots;
    for (int k = 1; k <= advanced; k++) dotEaten[(prevPacStepIdx + k) % totalDots] = true;
    int advancedGhost = (ghostVisIdx[3] - prevGhostBackIdx + totalDots) % totalDots;
    for (int k = 1; k <= advancedGhost; k++) dotEaten[(prevGhostBackIdx + k) % totalDots] = false;
  }
  if (pelletVisible && !dotEaten[pelletTrackIdx] && ((ms/300)%2)) {
    drawPowerPellet(CORNER_XY[pelletCorner][0], CORNER_XY[pelletCorner][1], bigDot);
  }
  for (int i = 0; i < totalDots; i++) {
    if (dotEaten[i]) continue;
    display->drawPixel(pathX[i], pathY[i], dot);
  }

  int pacFrame = (ms / 200) % 3;
  int px = pathX[pacStepIdx], py = pathY[pacStepIdx];
  int rawDir = pacPathDir(pacStepIdx);
  // Flip to face backward on every edge (not just top/bottom) while giving
  // chase -- restricting the flip to the long edges used to leave him
  // facing the wrong way whenever frightened mode caught him on the short
  // left/right columns.
  int dir = goingBackward ? (rawDir + 2) % 4 : rawDir;
  if (dir == 0) {
    if (pacFrame == 0) blit_pac_pacman1(px-4, py-4);
    else if (pacFrame == 1) blit_pac_pacman2(px-4, py-4);
    else blit_pac_pacman3(px-4, py-4);
  } else if (dir == 1) {
    if (pacFrame == 0) blit_pac_pacman1_down(px-4, py-4);
    else if (pacFrame == 1) blit_pac_pacman2_down(px-4, py-4);
    else blit_pac_pacman3_down(px-4, py-4);
  } else if (dir == 2) {
    if (pacFrame == 0) blit_pac_pacman1_left(px-4, py-4);
    else if (pacFrame == 1) blit_pac_pacman2_left(px-4, py-4);
    else blit_pac_pacman3_left(px-4, py-4);
  } else {
    if (pacFrame == 0) blit_pac_pacman1_up(px-4, py-4);
    else if (pacFrame == 1) blit_pac_pacman2_up(px-4, py-4);
    else blit_pac_pacman3_up(px-4, py-4);
  }

  // Ghosts: turn blue and flee backward while frightened. Position/flip
  // for each already computed above (needed earlier for the dot-eaten
  // span), so this just draws them.
  struct { const uint16_t *d; uint8_t w; uint8_t h; } ghosts[4] = {
    { pac_ghost_red, 8, 8 }, { pac_ghost_pink, 9, 8 },
    { pac_ghost_cyan, 8, 8 }, { pac_ghost_orange, 8, 8 }
  };
  for (int g = 0; g < 4; g++) {
    int gx = pathX[ghostVisIdx[g]] - ghosts[g].w/2, gy = pathY[ghostVisIdx[g]] - ghosts[g].h/2;
    blit_ghost_sprite(ghosts[g].d, ghosts[g].w, ghosts[g].h, gx, gy, ghostFlip[g], frightened, frightColor);
  }

  pacLastMs = (long)ms;

  // Enlarged HH:MM:SS clock, flanked by cherries (classic Pac-Man bonus fruit).
  // Sized/positioned to clear the loop sprites, which occupy y0-10 (top edge)
  // and y21-31 (bottom edge) at their widest.
  char buf[9];
  buf[0]='0'+h/10; buf[1]='0'+h%10; buf[2]=':';
  buf[3]='0'+m/10; buf[4]='0'+m%10; buf[5]=':';
  buf[6]='0'+s/10; buf[7]='0'+s%10; buf[8]=0;
  uint16_t yellow = c565(255,220,0);
  int textX = 17, textY = 12;
  for (int i = 0; i < 8; i++) {
    if (isColonHidden(buf[i], ms)) continue;
    drawWideFontChar(textX + i*12, textY, buf[i], yellow);
  }
  blit_pac_fruit_cherry(9, textY);
  blit_pac_fruit_cherry(113, textY);
}
// ── THEME 4: SPACE INVADERS ──────────────────
// Scripted wave, entirely a pure function of ms (no static state, so no
// unsigned-long-wrap risk and no need to guard against ms restarting when
// this theme is re-shown): the 18 aliens die one at a time on a fixed
// bottom-to-top, boustrophedon schedule (band = 2-row, alternating scan
// direction per band), the ship strafes to sit above whichever alien is
// next and fires straight up, a hit alien bursts then disappears, and once
// the wave is cleared the saucer flies in, gets hit in a big explosion,
// and the whole thing loops (localMs wraps back to 0) with all aliens back.
static void drawTheme_Invaders(int h, int m, int s, unsigned long ms) {
  display->fillRect(0, 0, 128, 32, c565(0,0,0));

  const int FIRE_PERIOD = 750, FLIGHT_TIME = 400, EXPLOSION_MS = 200;
  const int UFO_APPEAR_DELAY = 800, UFO_FLY_TIME = 2200, UFO_EXPLOSION_MS = 400, PAUSE_MS = 800;

  // 24 firing attempts to kill 18 aliens: a fixed, hand-authored pattern of
  // 6 misses interleaved with hits (so the ship doesn't connect every
  // single time), in the same bottom-to-top boustrophedon target order as
  // before. attemptTarget[i] = which alien (kill-schedule index 0-17)
  // attempt i is aimed at; attemptHit[i] = whether it connects;
  // missJitterX[i] = the sideways offset applied only on a miss -- that
  // offset *is* why it misses, the ship just wasn't quite centered.
  const int NATTEMPTS = 24;
  const int attemptTarget[24] = {0,1,2,2,3,4,5,6,6,7,8,9,9,10,11,11,12,13,14,14,15,16,17,17};
  const bool attemptHit[24]   = {true,true,false,true,true,true,true,false,true,true,true,false,true,true,false,true,true,true,false,true,true,true,false,true};
  const int missJitterX[24]   = {0,0,5,0,0,0,0,-6,0,0,0,4,0,0,-5,0,0,0,6,0,0,0,-4,0};
  // killAttempt[k] = the attempt index at which alien k actually dies (the
  // position of its corresponding "true" in attemptHit) -- used to time
  // each alien's death in the per-row draws below.
  const int killAttempt[18] = {0,1,3,4,5,6,8,9,10,12,13,15,16,17,19,20,21,23};

  const unsigned long lastKillMs = (unsigned long)killAttempt[17]*FIRE_PERIOD + FLIGHT_TIME;
  const unsigned long ufoAppearMs = lastKillMs + UFO_APPEAR_DELAY;
  const unsigned long ufoHitMs = ufoAppearMs + UFO_FLY_TIME;
  const unsigned long ufoExplosionEndMs = ufoHitMs + UFO_EXPLOSION_MS;
  const unsigned long WAVE_MS = ufoExplosionEndMs + PAUSE_MS;
  unsigned long localMs = ms % WAVE_MS;

  // Marching formation - amplitude widened to sweep almost the full 128px
  // width (was an 11px wobble) since there was unused margin on the left.
  const int MARCH_AMP = 46;
  int marchPhase = (int)((ms / 80) % (2*MARCH_AMP));
  int marchX = marchPhase < MARCH_AMP ? marchPhase : (2*MARCH_AMP - marchPhase);
  int invFrame = (ms / 400) % 2;

  const int nCol = 6, colSpacing = 14, startX = 4;
  const int rowY0 = 0, rowY1 = 8, rowY2 = 16;

  // Row 0: Squid (top, green) - band 2, killed last, left-to-right
  for (int col = 0; col < nCol; col++) {
    int i = 12 + col;
    unsigned long killMs = (unsigned long)killAttempt[i]*FIRE_PERIOD + FLIGHT_TIME;
    if (localMs >= killMs) continue;
    int ix = startX + col*colSpacing + marchX;
    if (ix > -8 && ix < 128) {
      if (invFrame==0) blit_inv_squid_0(ix, rowY0);
      else blit_inv_squid_1(ix, rowY0);
    }
  }
  // Row 1: Crab (middle, cyan) - band 1, killed second, right-to-left
  for (int col = 0; col < nCol; col++) {
    int i = 6 + (5 - col);
    unsigned long killMs = (unsigned long)killAttempt[i]*FIRE_PERIOD + FLIGHT_TIME;
    if (localMs >= killMs) continue;
    int ix = startX + col*colSpacing + marchX;
    if (ix > -8 && ix < 128) {
      if (invFrame==0) blit_inv_crab_0(ix, rowY1);
      else blit_inv_crab_1(ix, rowY1);
    }
  }
  // Row 2: Octopus (bottom, magenta) - band 0, killed first, left-to-right
  for (int col = 0; col < nCol; col++) {
    int i = col;
    unsigned long killMs = (unsigned long)killAttempt[i]*FIRE_PERIOD + FLIGHT_TIME;
    if (localMs >= killMs) continue;
    int ix = startX + col*colSpacing + marchX;
    if (ix > -8 && ix < 128) {
      if (invFrame==0) blit_inv_octopus_0(ix, rowY2);
      else blit_inv_octopus_1(ix, rowY2);
    }
  }

  // Bunkers (4 static shields, red) - sit right below the invader rows,
  // in the band freed up by moving the clock digits down to y=25.
  int bunkerX[4] = {6, 42, 78, 110};
  for (int b = 0; b < 4; b++) blit_inv_bunker(bunkerX[b], 22);

  // Current attempt, its target alien (row,col), whether it connects, and
  // the jitter that explains a miss.
  int curAttempt = (int)(localMs / FIRE_PERIOD);
  if (curAttempt > NATTEMPTS-1) curAttempt = NATTEMPTS-1;
  int curTarget = attemptTarget[curAttempt];
  bool curIsHit = attemptHit[curAttempt];
  int curJitter = curIsHit ? 0 : missJitterX[curAttempt];
  int curBand = curTarget / 6;
  int curWithin = curTarget % 6;
  int curRow = 2 - curBand;
  int curCol = (curBand % 2 == 0) ? curWithin : (5 - curWithin);
  int curRowY = (curRow==0) ? rowY0 : (curRow==1) ? rowY1 : rowY2;
  int curTargetX = startX + curCol*colSpacing + marchX + curJitter;

  // Ship: strafes to sit above (or just beside, on a miss) its current
  // target, gliding to the next attempt's aim point in the last 20% of
  // each firing period -- the randomness in where it ends up is what
  // makes it miss sometimes, same offset the bullet uses.
  int shipX;
  if (localMs >= ufoAppearMs) {
    shipX = 64; // idle center during the saucer sequence
  } else {
    unsigned long periodStart = (unsigned long)curAttempt * FIRE_PERIOD;
    unsigned long into = localMs - periodStart;
    unsigned long glideStart = (unsigned long)(FIRE_PERIOD * 8 / 10);
    if (into < glideStart) {
      shipX = curTargetX;
    } else {
      int nextAttempt = (curAttempt < NATTEMPTS-1) ? curAttempt + 1 : curAttempt;
      int nTarget = attemptTarget[nextAttempt];
      bool nIsHit = attemptHit[nextAttempt];
      int nJitter = nIsHit ? 0 : missJitterX[nextAttempt];
      int nBand = nTarget / 6, nWithin = nTarget % 6;
      int nCol2 = (nBand % 2 == 0) ? nWithin : (5 - nWithin);
      int nextTargetX = (nextAttempt == curAttempt) ? 64 : (startX + nCol2*colSpacing + marchX + nJitter);
      long span = FIRE_PERIOD - (long)glideStart;
      // clamp: once curAttempt is pinned at its max, "into" keeps growing
      // past FIRE_PERIOD (periodStart no longer advances with it) -- without
      // this the interpolation fraction exceeds 1 and overshoots past the
      // target instead of settling there.
      long t = (long)(into - glideStart);
      if (t > span) t = span;
      if (t < 0) t = 0;
      shipX = curTargetX + (int)((long)(nextTargetX - curTargetX) * t / span);
    }
  }
  blit_inv_ship(shipX - 5, 25);

  // Bullet: visible while the current attempt is in flight.
  unsigned long fireMs = (unsigned long)curAttempt * FIRE_PERIOD;
  unsigned long resolveMs = fireMs + FLIGHT_TIME;
  if (localMs >= fireMs && localMs < resolveMs) {
    unsigned long into = localMs - fireMs;
    int fromY = 24, toY = curRowY + 5;
    int by = fromY - (int)((long)(fromY - toY) * into / FLIGHT_TIME);
    blit_inv_missile(curTargetX + 3, by);
  }

  // Explosion burst -- only on a hit; a miss just goes quiet, alien intact
  // (filtered out by the per-row kill checks above once it does die).
  if (curIsHit && localMs >= resolveMs && localMs < resolveMs + EXPLOSION_MS) {
    blit_inv_explosion(curTargetX - 1, curRowY - 1);
  }

  // Saucer: appears once the wave is cleared, flies to center, gets hit in
  // a big explosion, then the wave respawns (localMs wraps back to 0).
  if (localMs >= ufoAppearMs && localMs < ufoHitMs) {
    unsigned long t = localMs - ufoAppearMs;
    int saucerX = -10 + (int)((70L * t) / UFO_FLY_TIME);
    blit_inv_saucer(saucerX, 0);
  } else if (localMs >= ufoHitMs && localMs < ufoHitMs + UFO_EXPLOSION_MS) {
    blit_inv_explosion_big(54, -1);
  }

  // Time split on each side of ship, y=25 to clear the bunker band above.
  // Colors match the reference HUD: SCORE-1 cyan (hours, left) / SCORE-2
  // yellow (minutes, right).
  uint16_t hourColor = c565(0,220,220);
  uint16_t minColor = c565(220,220,0);
  char buf[5];
  buf[0]='0'+h/10; buf[1]='0'+h%10; buf[2]=':'; buf[3]='0'+m/10; buf[4]='0'+m%10;
  // Hours on the left
  drawFontChar(15, 25, buf[0], hourColor);
  drawFontChar(24, 25, buf[1], hourColor);
  // Colon blinking in center area
  if (!isColonHidden(':', ms)) drawFontChar(62, 25, ':', c565(240,240,240));
  // Minutes on the right
  drawFontChar(98, 25, buf[3], minColor);
  drawFontChar(107, 25, buf[4], minColor);
}

// ── THEME 9: PONG (SCORE CLOCK) ──────────────
// Ball bounces between paddles, digits are the score display.
static void drawTheme_Pong(int h, int m, int s, unsigned long ms) {
  display->fillRect(0, 0, 128, 32, c565(0,0,0));

  // Center dashed line
  for (int y = 0; y < 32; y += 4)
    display->drawPixel(64, y, c565(60,60,60));

  uint16_t paddleCol = c565(200,200,200);
  int paddleH = 8;

  // Ball path: amplitude 59 puts its edge exactly on each paddle's inner
  // edge (paddles sit at x=2..3 and x=124..125) so it visibly touches
  // before reversing, instead of turning around a few pixels short.
  int ballPhase = (ms / 12) % 256;
  int ballXoff = sin8[ballPhase] * 59 / 127;
  int ballYoff = sin8[(ballPhase + 64) % 256] * 12 / 127;
  int bx = 64 + ballXoff;
  int by = 14 + ballYoff;
  if (by < 2) by = 2;
  if (by > 28) by = 28;

  // Paddles (auto-play): track the ball's current height (like a return
  // volley), so whichever side the ball is approaching is already lined
  // up to meet it.
  int py = by - paddleH/2;
  if (py < 0) py = 0;
  if (py > 32 - paddleH) py = 32 - paddleH;
  display->fillRect(2, py, 2, paddleH, paddleCol);
  display->fillRect(124, py, 2, paddleH, paddleCol);

  display->fillRect(bx-1, by-1, 3, 3, c565(200,200,200));

  // Clock digits as score (HH:MM)
  uint16_t scoreCol = c565(255,180,0);
  char buf[5];
  buf[0] = '0'+h/10; buf[1] = '0'+h%10; buf[2]=':'; buf[3]='0'+m/10; buf[4]='0'+m%10;

  // Evenly spaced at a uniform 12px pitch (was 12,10,14,12 -- an uneven
  // gap either side of the colon that read as off-center); centered so
  // the colon sits at x=64, on the dashed line.
  const uint8_t px[5] = {38, 50, 62, 74, 86};
  for (int i = 0; i < 5; i++) {
    if (isColonHidden(buf[i], ms)) continue;
    if (i == 2) {
      // Draw the colon as two of the line's own dashes recolored, so it
      // reads as sitting on the dashed line rather than floating between
      // dashes (the stock 5x7 colon glyph's dots don't land on the 4px
      // dash grid).
      display->drawPixel(64, 12, scoreCol);
      display->drawPixel(64, 16, scoreCol);
    } else {
      drawFontChar(px[i], 8, buf[i], scoreCol);
    }
  }

  // Score underline
  display->drawRect(34, 16, 60, 1, c565(80,60,0));
}

// ── THEME 5: NEON ──────────────────────────
// Large glowing neon tube digits (pink + blue, pulsing) — the base ("pink")
// hue comes from CLOCK_COLOR when the user has set one (clockNeonCustomColor),
// otherwise the original pink/blue duo is used. The second hue is always the
// RGB inverse of the base, so any chosen color still gets a contrasting
// colon/companion tone for free.
static uint16_t neonLayer(uint8_t r, uint8_t g, uint8_t b, int pulse, int pct) {
  return c565((pulse*r/255)*pct/100, (pulse*g/255)*pct/100, (pulse*b/255)*pct/100);
}

static void drawTheme_Neon(int h, int m, int s, unsigned long ms) {
  display->fillRect(0, 0, 128, 32, c565(0,0,0));
  int pulse = (sin8_ms(ms, 120) + 128) * 200 / 255;

  uint8_t baseR = 255, baseG = 40, baseB = 120;   // default: pink
  if (clockNeonCustomColor) { baseR = clockNeonR; baseG = clockNeonG; baseB = clockNeonB; }
  uint8_t altR = 255 - baseR, altG = 255 - baseG, altB = 255 - baseB; // contrasting companion hue

  uint16_t bright    = c565(baseR, baseG, baseB);
  uint16_t altBright  = c565(altR, altG, altB);
  uint16_t core       = neonLayer(baseR, baseG, baseB, pulse, 87);
  uint16_t altCore     = neonLayer(altR, altG, altB, pulse, 87);
  uint16_t mid        = neonLayer(baseR, baseG, baseB, pulse, 62);
  uint16_t altMid      = neonLayer(altR, altG, altB, pulse, 62);
  uint16_t smudge     = neonLayer(baseR, baseG, baseB, pulse, 20);
  uint16_t altSmudge   = neonLayer(altR, altG, altB, pulse, 20);

  const uint8_t lx[5] = {6, 30, 54, 78, 102};
  char buf[5];
  buf[0]='0'+h/10; buf[1]='0'+h%10; buf[2]=':'; buf[3]='0'+m/10; buf[4]='0'+m%10;
  for (int i = 0; i < 5; i++) {
    if (isColonHidden(buf[i], ms)) continue;
    uint16_t layerSmudge = (i==2) ? altSmudge : smudge;
    uint16_t layerMid = (i==2) ? altMid : mid;
    uint16_t layerCore = (i==2) ? altCore : core;
    uint16_t layerBright = (i==2) ? altBright : bright;
    drawLargeFontChar(lx[i]-4, 2, buf[i], layerSmudge);
    drawLargeFontChar(lx[i]+4, 2, buf[i], layerSmudge);
    drawLargeFontChar(lx[i]-2, 2, buf[i], layerMid);
    drawLargeFontChar(lx[i]+2, 2, buf[i], layerMid);
    drawLargeFontChar(lx[i], 2, buf[i], layerCore);
    drawLargeFontChar(lx[i], 2, buf[i], layerBright);
  }
}

// ── THEME 6: MATRIX ────────────────────────
// Large matrix-green digits with glitch effects
static void drawTheme_Matrix(int h, int m, int s, unsigned long ms) {
  display->fillRect(0, 0, 128, 32, c565(0,0,0));
  const uint8_t lx[5] = {6, 30, 54, 78, 102};
  char buf[5];
  buf[0]='0'+h/10; buf[1]='0'+h%10; buf[2]=':'; buf[3]='0'+m/10; buf[4]='0'+m%10;
  for (int i = 0; i < 5; i++) {
    if (isColonHidden(buf[i], ms)) continue;
    drawLargeFontChar(lx[i]+2, 4, buf[i], c565(0,60,0));
    drawLargeFontChar(lx[i], 2, buf[i], c565(0,255,0));
  }
  for (int p = 0; p < 5; p++) {
    int sx = (p*31 + ms/30) % 108 + 10;
    int sy = (p*17 + ms/20) % 28 + 2;
    if ((ms/40 + p*10) % 7 < 3)
      display->drawPixel(sx, sy, c565(180,255,180));
  }
  for (int d = 0; d < 5; d++) {
    int rx = (d*23 + ms/60) % 100 + 14;
    int ry = (d*13 + ms/12) % 24 + 4;
    char rc = "0123456789ABCDEF"[(d*7 + ms/100) % 16];
    drawFontChar(rx, ry, rc, c565(0,100+(ry%3)*50,0));
  }
}

// ── THEME 7: FIRE ──────────────────────────
// Large fire digits with per-row flame coloring
static void drawTheme_Fire(int h, int m, int s, unsigned long ms) {
  display->fillRect(0, 0, 128, 32, c565(0,0,0));
  const uint8_t lx[5] = {6, 30, 54, 78, 102};
  char buf[5];
  buf[0]='0'+h/10; buf[1]='0'+h%10; buf[2]=':'; buf[3]='0'+m/10; buf[4]='0'+m%10;
  for (int ci = 0; ci < 5; ci++) {
    if (isColonHidden(buf[ci], ms)) continue;
    int idx = -1;
    for (int i = 0; i < 11; i++) { if (font_chars[i] == buf[ci]) { idx = i; break; } }
    if (idx < 0) continue;
    uint8_t rows[7];
    memcpy_P(rows, font5x7[idx], 7);
    for (int row = 0; row < 7; row++) {
      for (int col = 0; col < 5; col++) {
        if (rows[row] & (0x10 >> col)) {
          int wobX = (sin8[(row*13+col*7+ci*30+ms/10)%256]-128)/64;
          int wobY = (sin8[(row*11+col*9+ci*40+ms/12)%256]-128)/64;
          int bx = lx[ci] + col*4 + wobX;
          int by = 2 + row*4 + wobY;
          int fl = (sin8[(row*31+col*17+ms/8)%256]+128)/10;
          uint8_t r,g,b;
          if (row >= 5) { r=255; g=180+fl; if(g>255)g=255; b=80+fl/2; if(b>255)b=255; }
          else if (row >= 3) { r=255; g=100+fl; b=fl/4; }
          else if (row >= 1) { r=180+fl; if(r>255)r=255; g=20+fl/5; b=0; }
          else { r=100+fl/3; g=5; b=0; }
          display->fillRect(bx, by, 4, 4, c565(r,g,b));
        }
      }
    }
  }
  for (int w = 0; w < 4; w++) {
    int wx = (w*31+ms/40)%108+10;
    int wy = 31-(ms/60+w*17)%28;
    int wh = 2+(w%3);
    for (int p = 0; p < wh; p++) {
      int t = (ms/25+w*41+p*60)%256;
      display->drawPixel(wx+p-1, wy-p, c565(255,100+t/4,0));
    }
  }
}

// ── THEME 8: RAINBOW ───────────────────────
// Large rainbow-cycling digits with sparkles
static void drawTheme_Rainbow(int h, int m, int s, unsigned long ms) {
  display->fillRect(0, 0, 128, 32, c565(0,0,15));
  const uint8_t lx[5] = {6, 30, 54, 78, 102};
  char buf[5];
  buf[0]='0'+h/10; buf[1]='0'+h%10; buf[2]=':'; buf[3]='0'+m/10; buf[4]='0'+m%10;
  for (int ci = 0; ci < 5; ci++) {
    if (isColonHidden(buf[ci], ms)) continue;
    int yOff = sin8[(ms/20 + ci*60) % 256] / 30;
    int idx = -1;
    for (int i = 0; i < 11; i++) { if (font_chars[i] == buf[ci]) { idx = i; break; } }
    if (idx < 0) continue;
    uint8_t rows[7];
    memcpy_P(rows, font5x7[idx], 7);
    for (int row = 0; row < 7; row++) {
      for (int col = 0; col < 5; col++) {
        if (rows[row] & (0x10 >> col)) {
          int bx = lx[ci] + col*4;
          int by = 2 + yOff + row*4;
          int hue = (ms/30 + ci*30 + row*20 + col*35) % 256;
          uint8_t r,g,b;
          int hp = hue % 85;
          if (hue < 85)       { r=255-hp*3; g=hp*3;   b=0; }
          else if (hue < 170) { r=0;        g=255-hp*3; b=hp*3; }
          else                { r=hp*3;     g=0;        b=255-hp*3; }
          display->fillRect(bx, by, 4, 4, c565(r,g,b));
        }
      }
    }
  }
  for (int s2 = 0; s2 < 6; s2++) {
    int sx = (s2*29 + ms/60) % 118 + 5;
    int sy = (s2*17 + ms/50) % 28 + 2;
    int sh = (ms/15 + s2*73) % 256;
    int h2 = sh % 85;
    uint8_t r,g,b;
    if (sh < 85)       { r=255-h2*3; g=h2*3;   b=0; }
    else if (sh < 170) { r=0;        g=255-h2*3; b=h2*3; }
    else               { r=h2*3;     g=0;        b=255-h2*3; }
    display->drawPixel(sx, sy, c565(r,g,b));
  }
}
// ── MAIN DISPATCHER ──────────────────────────────────────────
#define RETRO_THEME_COUNT 10

static void drawRetroClockTheme(int theme, int h, int m, int s, unsigned long ms) {
  switch (theme) {
    case 0: drawTheme_Mario(h, m, s, ms); break;
    case 1: drawTheme_Tetris(h, m, s, ms); break;
    case 2: drawTheme_Pacman(h, m, s, ms); break;
    case 3: drawTheme_Invaders(h, m, s, ms); break;
    case 4: drawTheme_Pong(h, m, s, ms); break;
    case 5: drawTheme_Neon(h, m, s, ms); break;
    case 6: drawTheme_Matrix(h, m, s, ms); break;
    case 7: drawTheme_Fire(h, m, s, ms); break;
    case 8: drawTheme_Rainbow(h, m, s, ms); break;
    case 9: drawTheme_Level11(h, m, s, ms); break;
  }
}

static const char* retroThemeNames[RETRO_THEME_COUNT] = {
  "Super Mario", "Tetris", "Pac-Man",
  "Space Invaders", "Pong",
  "Neon", "Matrix", "Fire", "Rainbow", "Level 1-1"
};

#endif // CLOCK_THEMES_H
